import sys
from collections import deque

class T:
    __slots__ = ('v', 'l', 'r')
    def __init__(self, v=0, l=None, r=None):
        self.v = v; self.l = l; self.r = r

def build(arr):
    if not arr or arr[0] == 'n':
        return None
    root = T(int(arr[0]))
    q = deque([root]); i = 1
    while q and i < len(arr):
        node = q.popleft()
        if i < len(arr) and arr[i] != 'n':
            node.l = T(int(arr[i])); q.append(node.l)
        i += 1
        if i < len(arr) and arr[i] != 'n':
            node.r = T(int(arr[i])); q.append(node.r)
        i += 1
    return root

def path_brute(root, target):
    def from_node(node, cur):
        if node is None:
            return 0
        cur += node.v
        c = 1 if cur == target else 0
        c += from_node(node.l, cur) + from_node(node.r, cur)
        return c
    if root is None:
        return 0
    cnt = from_node(root, 0)
    cnt += path_brute(root.l, target) + path_brute(root.r, target)
    return cnt

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    target = int(data[1 + n])
    root = build(data[1:1 + n])
    print(path_brute(root, target))

import sys
from collections import deque

class T:
    __slots__ = ('v', 'l', 'r')
    def __init__(self, v=0, l=None, r=None):
        self.v = v; self.l = l; self.r = r

def build(arr):
    if not arr or arr[0] == 'n':
        return None
    root = T(int(arr[0]))
    q = deque([root]); i = 1
    while q and i < len(arr):
        node = q.popleft()
        if i < len(arr) and arr[i] != 'n':
            node.l = T(int(arr[i])); q.append(node.l)
        i += 1
        if i < len(arr) and arr[i] != 'n':
            node.r = T(int(arr[i])); q.append(node.r)
        i += 1
    return root

def path_best(root, target):
    from collections import defaultdict
    pref = defaultdict(int)
    pref[0] = 1
    def dfs(node, cur):
        if node is None:
            return 0
        cur += node.v
        c = pref[cur - target]
        pref[cur] += 1
        c += dfs(node.l, cur) + dfs(node.r, cur)
        pref[cur] -= 1
        return c
    return dfs(root, 0)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    target = int(data[1 + n])
    root = build(data[1:1 + n])
    print(path_best(root, target))
